    if (pages <= 7) for (let i = 1; i <= pages; i++) add(i);
    else { add(1); if (page > 4) add('…'); for (let i = Math.max(2, page - 1); i <= Math.min(pages - 1, page + 1); i++) add(i); if (page < pages - 3) add('…'); add(pages); }
