      '<button type="button" class="uk-lb-nav is-prev" aria-label="上一个">' + icon('chevronLeft') + '</button><div class="uk-lb-stage"></div>' +
      '<button type="button" class="uk-lb-nav is-next" aria-label="下一个">' + icon('chevronRight') + '</button><div class="uk-lb-meta"></div>';
