    tray.querySelector('.uk-tray-head b').textContent = run ? '正在上传 ' + (ok + 1 > jobs.length ? jobs.length : ok + 1) + ' / ' + jobs.length : fail ? ok + ' 个完成，' + fail + ' 个失败' : '已上传 ' + ok + ' 个文件';
