      groups.forEach((g) => { if (g && !g.reported && g.every((j) => j.state === 'ok' || j.state === 'fail')) { g.reported = true; g[0].o.onDone && g[0].o.onDone(g.filter((j) => j.state === 'ok').length, g.filter((j) => j.state === 'fail').length); } });
